```csharp
// PriceCalculator.cs
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegative(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal price, int discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(price);
        if (discountPercent is < 0 or > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));
        return price * (100 - discountPercent) / 100m;
    }
}
```

```csharp
// PriceCalculatorTests.cs
[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // ── CalculateTotal: DataRow for simple inline cases ──

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(10.00, 3, 30.00, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00,   DisplayName = "Zero price")]
    [DataRow(25.50, 0, 0.00,  DisplayName = "Zero quantity")]
    [DataRow(99.99, 2, 199.98, DisplayName = "Fractional price")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1)]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, -1)]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    // ── ApplyDiscount: DynamicData with ValueTuples for complex/decimal data ──

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m,  10,  90m),
        (200m,  25, 150m),
        (50m,    0,  50m),
        (80m,  100,   0m),
        (99.99m, 50, 49.995m),
    ];

    // DynamicData with TestDataRow for display names

    [TestMethod]
    [DynamicData(nameof(DiscountEdgeCases))]
    public void ApplyDiscount_EdgeCases_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<TestDataRow<(decimal price, int percent, decimal expected)>>
        DiscountEdgeCases =>
    [
        new((0m, 50, 0m))        { DisplayName = "Zero price, any discount" },
        new((1000m, 1, 990m))    { DisplayName = "Minimal 1% discount" },
        new((1000m, 99, 10m))    { DisplayName = "Near-total 99% discount" },
    ];

    // Invalid discount percentages

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_Throws(int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }

    [TestMethod]
    public void ApplyDiscount_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(-10m, 10));
    }
}
```

**Key patterns used:**

| Pattern | When | Example above |
|---|---|---|
| `[DataRow]` | Simple inline values (`int`, `double`, `string`) | `CalculateTotal` tests |
| `DynamicData` + ValueTuple | Complex types like `decimal`, or many params | `DiscountTestData` |
| `TestDataRow<T>` | Need per-case `DisplayName` with complex data | `DiscountEdgeCases` |
| `Assert.ThrowsExactly<T>` | Exception testing (replaces `[ExpectedException]`) | Invalid input tests |

**Notes:**
- `DataRow` doesn't support `decimal` literals directly — use `double` and cast, or prefer `DynamicData` for decimal-heavy scenarios.
- Seal test classes (`sealed`) for performance.
- ValueTuple-based `DynamicData` (MSTest 3.7+) gives type safety over `IEnumerable<object[]>`.
- Use `[TestMethod]` (not `[DataTestMethod]`) — it handles data rows since MSTest 3.x.
